    void prepareSelectedModel(){
        long existing=prefs.getLong("model_download_id",-1);if(existing>0){Toast.makeText(this,"A model is already downloading. Cancel it before choosing another.",Toast.LENGTH_LONG).show();return;}
        String mode=prefs.getString("ai_mode",MODEL_OFF);if(mode.equals(MODEL_OFF)){Toast.makeText(this,"Choose a model above first.",Toast.LENGTH_SHORT).show();return;}
        File target=modelFile(mode);long expected=expectedModelBytes(mode);
        if(target.isFile()&&target.length()==expected){new Thread(()->{boolean valid=sha256(target).equals(expectedModelHash(mode));runOnUiThread(()->{if(valid){Toast.makeText(this,"On-device model is ready.",Toast.LENGTH_SHORT).show();build();}else{target.delete();confirmModelDownload(mode);}});}).start();return;}
        if(target.exists())target.delete();confirmModelDownload(mode);
    }
