        String file=mode.equals(MODEL_SMALL)?SMALL_FILE:STANDARD_FILE;String repo=mode.equals(MODEL_SMALL)?"SmolLM2 135M":"Qwen3 0.6B INT4";String url=mode.equals(MODEL_SMALL)?"https://huggingface.co/litert-community/SmolLM2-135M-Instruct/resolve/749fc23bc8d7ef89db031d075004289c88f41c2f/SmolLM2_135M_Instruct.litertlm":"https://huggingface.co/litert-community/Qwen3-0.6B/resolve/a3c5d805ae362dff7f580bc25f2dfb9a5a7eaa76/Qwen3-0.6B_dynamic_wi4b32_afp32.litertlm";
