    void watchModelDownload(long id){
        if(watchingDownloadId==id||verifyingDownloadId==id)return;if(downloadWatch!=null)handler.removeCallbacks(downloadWatch);watchingDownloadId=id;
        downloadWatch=new Runnable(){public void run(){if(isFinishing()||isDestroyed())return;try(Cursor c=downloadManager.query(new DownloadManager.Query().setFilterById(id))){if(c==null||!c.moveToFirst())return;int status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_RUNNING||status==DownloadManager.STATUS_PENDING||status==DownloadManager.STATUS_PAUSED){long got=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR)),total=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));if(modelStatusView!=null){String text=modelStatus();if(total>0)text="Downloading · "+(got/1000000)+" / "+(total/1000000)+" MB";modelStatusView.setText(text);}handler.postDelayed(this,1200);return;}
            String mode=prefs.getString("model_download_mode",MODEL_OFF);watchingDownloadId=-1;downloadWatch=null;
            if(status==DownloadManager.STATUS_SUCCESSFUL){verifyingDownloadId=id;File f=modelFile(mode);long expectedBytes=expectedModelBytes(mode);String expectedHash=expectedModelHash(mode);new Thread(()->{boolean valid=f.isFile()&&f.length()==expectedBytes&&sha256(f).equals(expectedHash);runOnUiThread(()->{if(prefs.getLong("model_download_id",-1)==id)prefs.edit().remove("model_download_id").remove("model_download_mode").apply();verifyingDownloadId=-1;if(!valid){f.delete();Toast.makeText(MainActivity.this,"The download was incomplete or failed its integrity check. The partial file was removed; you can try again on Wi-Fi.",Toast.LENGTH_LONG).show();}else{legacyStandardModelFile().delete();Toast.makeText(MainActivity.this,"Model ready · it now runs offline on this phone.",Toast.LENGTH_LONG).show();}build();});}).start();
            }else{if(prefs.getLong("model_download_id",-1)==id)prefs.edit().remove("model_download_id").remove("model_download_mode").apply();if(modelStatusView!=null)modelStatusView.setText("Download stopped. Try again when you’re ready.");if(modelDownloadButton!=null)modelDownloadButton.setText(modelButtonLabel());}
        }catch(Exception e){watchingDownloadId=-1;downloadWatch=null;prefs.edit().remove("model_download_id").remove("model_download_mode").apply();if(modelStatusView!=null)modelStatusView.setText("Download status unavailable. You can try again.");}}};handler.postDelayed(downloadWatch,700);
    }
    void cancelModelDownload(){long id=prefs.getLong("model_download_id",-1);if(id<=0)return;String mode=prefs.getString("model_download_mode",MODEL_OFF);downloadManager.remove(id);if(downloadWatch!=null)handler.removeCallbacks(downloadWatch);watchingDownloadId=-1;downloadWatch=null;verifyingDownloadId=-1;modelFile(mode).delete();prefs.edit().remove("model_download_id").remove("model_download_mode").remove("model_download_schema").apply();if(page.equals("More")){build();Toast.makeText(this,"Download cancelled and partial file removed.",Toast.LENGTH_SHORT).show();}}
    String sha256(File f){try{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0)md.update(buffer,0,n);}byte[] digest=md.digest();StringBuilder s=new StringBuilder();for(byte b:digest)s.append(String.format(Locale.US,"%02x",b&0xff));return s.toString();}catch(Exception e){return "";}}
