        TextView stepTwo=text("STEP 2  ·  REVIEW HARU’S IDEAS AND CHOOSE WHAT TO KEEP",10,muted,true);stepTwo.setPadding(dp(2),dp(8),dp(2),0);content.addView(stepTwo);Button ask=smallButton("Help me sort this out  →");ask.setTextColor(white);ask.setTextSize(14);ask.setBackground(gradient(purple,Color.rgb(133,106,180),18));ask.setOnClickListener(v->askHaru());content.addView(ask);String mode=prefs.getString("ai_mode",MODEL_OFF);String line=mode.equals(MODEL_OFF)?"Quick private suggestions are ready · AI is optional.":modelStatus();TextView privacy=text(line,11,muted,false);privacy.setGravity(Gravity.CENTER);content.addView(privacy);
